/* ==========================================================================
   StreamWave Entertainment - Serverless Media Platform Stylesheet
   Dark Graphite Theme with Restrained Red Accent
   ========================================================================== */

:root {
    --bg-base: #121214;
    --bg-surface: #18181c;
    --bg-elevated: #222228;
    --bg-hover: #2a2a32;

    --border-color: #2e2e38;
    --border-focus: #e50914;

    --text-primary: #f4f4f6;
    --text-secondary: #a0a0ab;
    --text-muted: #6e6e7a;

    --accent-red: #e50914;
    --accent-red-hover: #b80710;
    --accent-red-subtle: rgba(229, 9, 20, 0.15);

    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --radius-sm: 4px;
    --radius-md: 6px;

    --shadow-card: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-dialog: 0 16px 32px rgba(0, 0, 0, 0.7);
}

/* Base Resets */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-base);
    color: var(--text-primary);
    font-family: var(--font-family);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    padding-bottom: 90px; /* Space for fixed audio player */
}

a {
    color: inherit;
    text-decoration: none;
}

button, input, select {
    font-family: inherit;
    font-size: inherit;
}

/* Navigation Bar */
.navbar {
    background-color: var(--bg-surface);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.85rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.brand {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 800;
    font-size: 1.25rem;
    letter-spacing: -0.02em;
}

.logo-symbol {
    color: var(--accent-red);
    font-size: 1.1rem;
}

.logo-accent {
    color: var(--accent-red);
}

.nav-links {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.nav-link {
    color: var(--text-secondary);
    font-size: 0.9rem;
    font-weight: 500;
    transition: color 0.2s ease;
}

.nav-link:hover, .nav-link.active {
    color: var(--text-primary);
}

.api-link {
    color: var(--accent-red);
}

.serverless-badge {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    padding: 0.25rem 0.65rem;
    border-radius: var(--radius-sm);
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.pulse-dot {
    width: 6px;
    height: 6px;
    background-color: #10b981;
    border-radius: 50%;
    box-shadow: 0 0 8px #10b981;
}

/* Main Container */
.main-content {
    max-width: 1200px;
    width: 100%;
    margin: 0 auto;
    padding: 1.5rem;
    flex: 1;
}

/* Hero / Featured Section */
.hero-section {
    position: relative;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    padding: 2.5rem 2rem;
    margin-bottom: 2rem;
    overflow: hidden;
    background-image: linear-gradient(to right, rgba(24, 24, 28, 0.95) 40%, rgba(24, 24, 28, 0.6)), url('https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 650px;
}

.hero-tag {
    color: var(--accent-red);
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 0.5rem;
}

.hero-title {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 0.5rem;
    letter-spacing: -0.03em;
}

.hero-meta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-secondary);
    font-size: 0.85rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.meta-tag {
    background-color: var(--accent-red-subtle);
    color: var(--accent-red);
    padding: 0.1rem 0.4rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.75rem;
}

.meta-separator {
    color: var(--text-muted);
}

.hero-description {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
    line-height: 1.6;
}

.hero-actions {
    display: flex;
    gap: 0.85rem;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.6rem 1.2rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background-color 0.15s ease, border-color 0.15s ease;
}

.btn-primary {
    background-color: var(--accent-red);
    color: #ffffff;
}

.btn-primary:hover {
    background-color: var(--accent-red-hover);
}

.btn-secondary {
    background-color: var(--bg-elevated);
    color: var(--text-primary);
    border-color: var(--border-color);
}

.btn-secondary:hover {
    background-color: var(--bg-hover);
}

/* Catalogue Header & Toolbar */
.section-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: 1rem;
}

.section-title {
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: -0.02em;
}

.item-count {
    color: var(--text-muted);
    font-size: 0.85rem;
}

.toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.5rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    padding: 0.85rem 1rem;
    border-radius: var(--radius-md);
    align-items: center;
    justify-content: space-between;
}

.search-box {
    position: relative;
    flex: 1;
    min-width: 260px;
    display: flex;
    align-items: center;
}

.search-icon {
    position: absolute;
    left: 0.75rem;
    font-size: 0.9rem;
    color: var(--text-muted);
    pointer-events: none;
}

.search-box input {
    width: 100%;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.55rem 2.2rem 0.55rem 2.2rem;
    border-radius: var(--radius-sm);
    outline: none;
    transition: border-color 0.15s ease;
}

.search-box input:focus {
    border-color: var(--border-focus);
}

.clear-btn {
    position: absolute;
    right: 0.6rem;
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 1.1rem;
    cursor: pointer;
}

.clear-btn:hover {
    color: var(--text-primary);
}

.filter-group {
    display: flex;
    gap: 0.75rem;
    align-items: center;
    flex-wrap: wrap;
}

/* Tabs */
.type-tabs {
    display: flex;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    padding: 2px;
}

.type-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    padding: 0.4rem 0.9rem;
    border-radius: var(--radius-sm);
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
    transition: color 0.15s ease, background-color 0.15s ease;
}

.type-tab.active {
    background-color: var(--bg-hover);
    color: var(--text-primary);
    font-weight: 600;
}

/* Select */
.select-wrapper select {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.45rem 0.85rem;
    border-radius: var(--radius-sm);
    outline: none;
    cursor: pointer;
    font-size: 0.85rem;
}

.select-wrapper select:focus {
    border-color: var(--border-focus);
}

/* UI States */
.state-view {
    text-align: center;
    padding: 3rem 1rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
}

.state-icon {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.state-view h3 {
    font-size: 1.1rem;
    margin-bottom: 0.3rem;
}

.state-view p {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Spinner */
.spinner {
    width: 32px;
    height: 32px;
    border: 3px solid var(--border-color);
    border-top-color: var(--accent-red);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto 1rem auto;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Media Cards Grid */
.media-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 1.25rem;
}

.media-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.media-card:hover {
    transform: translateY(-2px);
    border-color: var(--text-muted);
}

.card-thumb-wrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    background-color: var(--bg-elevated);
    overflow: hidden;
}

.card-thumb {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.card-badge {
    position: absolute;
    top: 0.5rem;
    left: 0.5rem;
    background-color: rgba(18, 18, 20, 0.85);
    border: 1px solid var(--border-color);
    color: var(--accent-red);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.15rem 0.45rem;
    border-radius: var(--radius-sm);
    letter-spacing: 0.05em;
}

.card-content {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    flex: 1;
}

.card-title {
    font-size: 1rem;
    font-weight: 700;
    line-height: 1.25;
    margin-bottom: 0.25rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.card-subtitle {
    color: var(--text-secondary);
    font-size: 0.825rem;
    margin-bottom: 0.5rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.card-meta {
    display: flex;
    gap: 0.4rem;
    align-items: center;
    color: var(--text-muted);
    font-size: 0.775rem;
    margin-bottom: 0.85rem;
}

.card-actions {
    margin-top: auto;
    display: flex;
    gap: 0.5rem;
}

.card-actions .btn {
    flex: 1;
    padding: 0.45rem 0.6rem;
    font-size: 0.8rem;
}

/* Modal Dialog */
.details-dialog {
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background-color: var(--bg-surface);
    color: var(--text-primary);
    max-width: 580px;
    width: 90%;
    margin: auto;
    padding: 0;
    box-shadow: var(--shadow-dialog);
}

.details-dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(2px);
}

.dialog-content {
    position: relative;
    padding: 1.75rem;
}

.dialog-close {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-secondary);
    width: 32px;
    height: 32px;
    border-radius: 50%;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
}

.dialog-close:hover {
    color: var(--text-primary);
    border-color: var(--text-muted);
}

.dialog-header-meta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
}

.dialog-title {
    font-size: 1.6rem;
    font-weight: 800;
    line-height: 1.2;
    margin-bottom: 0.25rem;
}

.dialog-artist {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 1rem;
}

.dialog-description {
    color: var(--text-secondary);
    font-size: 0.9rem;
    line-height: 1.6;
    margin-bottom: 1.25rem;
    background-color: var(--bg-elevated);
    padding: 0.85rem 1rem;
    border-radius: var(--radius-sm);
    border-left: 3px solid var(--accent-red);
}

.dialog-info-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

.info-item {
    background-color: var(--bg-elevated);
    padding: 0.5rem 0.75rem;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
}

.info-label {
    font-size: 0.7rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.info-value {
    font-size: 0.85rem;
    font-weight: 600;
}

/* Audio Player Bar */
.audio-player-bar {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background-color: var(--bg-surface);
    border-top: 1px solid var(--border-color);
    padding: 0.75rem 1.5rem;
    z-index: 90;
}

.player-container {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.player-track-info {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    min-width: 220px;
    max-width: 300px;
}

.track-thumb {
    width: 40px;
    height: 40px;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
}

.track-text {
    overflow: hidden;
}

.track-title {
    font-size: 0.875rem;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.track-artist {
    font-size: 0.75rem;
    color: var(--text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.player-controls {
    flex: 1;
    display: flex;
    justify-content: center;
}

.player-controls audio {
    width: 100%;
    max-width: 500px;
    height: 38px;
}

.player-status {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.75rem;
    color: var(--text-muted);
    min-width: 140px;
    justify-content: flex-end;
}

.event-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background-color: var(--text-muted);
}

.event-dot.active {
    background-color: var(--accent-red);
    box-shadow: 0 0 6px var(--accent-red);
}

/* Responsive Media Queries */
@media (max-width: 768px) {
    .nav-container {
        flex-wrap: wrap;
    }

    .serverless-badge {
        display: none;
    }

    .hero-title {
        font-size: 1.8rem;
    }

    .toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .search-box {
        min-width: 100%;
    }

    .filter-group {
        flex-direction: column;
        align-items: stretch;
    }

    .type-tabs {
        justify-content: center;
    }

    .player-container {
        flex-direction: column;
        align-items: stretch;
        gap: 0.5rem;
    }

    .player-track-info {
        max-width: 100%;
    }

    body {
        padding-bottom: 130px;
    }
}

/**
 * StreamWave Entertainment - Frontend Application Logic
 * Academic Serverless Prototype
 */

(function () {
    'use strict';

    // App State
    const state = {
        media: [],
        activeType: '',
        activeGenre: '',
        searchQuery: '',
        currentTrack: null,
        sessionId: 'sess-' + Math.random().toString(36).substring(2, 9)
    };

    // DOM Elements
    const elements = {
        searchInput: document.getElementById('search-input'),
        clearSearchBtn: document.getElementById('clear-search'),
        typeTabs: document.querySelectorAll('.type-tab'),
        genreSelect: document.getElementById('genre-select'),
        itemCount: document.getElementById('item-count'),

        // Views
        loadingState: document.getElementById('loading-state'),
        errorState: document.getElementById('error-state'),
        errorMessage: document.getElementById('error-message'),
        emptyState: document.getElementById('empty-state'),
        mediaGrid: document.getElementById('media-grid'),

        // Modal
        detailsDialog: document.getElementById('details-dialog'),
        closeDialogBtn: document.getElementById('close-dialog'),
        dialogBody: document.getElementById('dialog-body'),

        // Audio Player
        audioElement: document.getElementById('html5-audio'),
        audioSource: document.getElementById('audio-source'),
        playerThumb: document.getElementById('player-thumb'),
        playerTitle: document.getElementById('player-title'),
        playerArtist: document.getElementById('player-artist'),
        eventLogText: document.getElementById('event-log-text'),
        eventDot: document.querySelector('.event-dot')
    };

    /**
     * Initializes event listeners and fetches initial media list
     */
    function init() {
        bindEvents();
        fetchMedia();
    }

    /**
     * Binds user interaction listeners
     */
    function bindEvents() {
        // Search input with debounce
        let searchTimeout;
        elements.searchInput.addEventListener('input', (e) => {
            state.searchQuery = e.target.value.trim();
            elements.clearSearchBtn.style.display = state.searchQuery ? 'block' : 'none';
            clearTimeout(searchTimeout);
            searchTimeout = setTimeout(() => fetchMedia(), 250);
        });

        elements.clearSearchBtn.addEventListener('click', () => {
            elements.searchInput.value = '';
            state.searchQuery = '';
            elements.clearSearchBtn.style.display = 'none';
            fetchMedia();
        });

        // Type tabs
        elements.typeTabs.forEach((tab) => {
            tab.addEventListener('click', () => {
                elements.typeTabs.forEach((t) => {
                    t.classList.remove('active');
                    t.setAttribute('aria-selected', 'false');
                });
                tab.classList.add('active');
                tab.setAttribute('aria-selected', 'true');
                state.activeType = tab.getAttribute('data-type');
                fetchMedia();
            });
        });

        // Genre filter select
        elements.genreSelect.addEventListener('change', (e) => {
            state.activeGenre = e.target.value;
            fetchMedia();
        });

        // Modal close button
        elements.closeDialogBtn.addEventListener('click', () => {
            elements.detailsDialog.close();
        });

        // Close modal on backdrop click
        elements.detailsDialog.addEventListener('click', (e) => {
            const rect = elements.detailsDialog.getBoundingClientRect();
            const isInDialog = (
                rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                rect.left <= e.clientX && e.clientX <= rect.left + rect.width
            );
            if (!isInDialog) {
                elements.detailsDialog.close();
            }
        });

        // Audio element playback listener to log play event
        elements.audioElement.addEventListener('play', () => {
            if (state.currentTrack) {
                logPlayEvent(state.currentTrack.id);
            }
        });
    }

    /**
     * Fetches media items from FastAPI backend /api/media endpoint
     */
    async function fetchMedia() {
        showView('loading');

        try {
            const params = new URLSearchParams();
            if (state.searchQuery) params.append('query', state.searchQuery);
            if (state.activeType) params.append('type', state.activeType);
            if (state.activeGenre) params.append('genre', state.activeGenre);

            const url = `/api/media${params.toString() ? '?' + params.toString() : ''}`;
            const response = await fetch(url);

            if (!response.ok) {
                throw new Error(`Server returned HTTP ${response.status}`);
            }

            state.media = await response.json();
            renderMediaGrid();
        } catch (err) {
            console.error('Error fetching media:', err);
            elements.errorMessage.textContent = err.message || 'Failed to connect to StreamWave API.';
            showView('error');
        }
    }

    /**
     * Renders media items in card grid
     */
    function renderMediaGrid() {
        elements.itemCount.textContent = `${state.media.length} item${state.media.length === 1 ? '' : 's'}`;

        if (state.media.length === 0) {
            showView('empty');
            return;
        }

        elements.mediaGrid.innerHTML = state.media.map((item) => `
            <article class="media-card" data-id="${item.id}">
                <div class="card-thumb-wrapper">
                    <img class="card-thumb" src="${item.cover_image || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=600&q=80'}" alt="${escapeHtml(item.title)}" loading="lazy">
                    <span class="card-badge">${escapeHtml(item.type)}</span>
                </div>
                <div class="card-content">
                    <h3 class="card-title">${escapeHtml(item.title)}</h3>
                    <div class="card-subtitle">${escapeHtml(item.artist_or_director)}</div>
                    <div class="card-meta">
                        <span>${item.year}</span>
                        <span>•</span>
                        <span>${escapeHtml(item.genre)}</span>
                        <span>•</span>
                        <span>${escapeHtml(item.duration)}</span>
                    </div>
                    <div class="card-actions">
                        <button class="btn btn-primary" onclick="window.streamWaveApp.playMedia('${item.id}')">
                            ▶ ${item.media_url ? 'Play Demo' : 'Play'}
                        </button>
                        <button class="btn btn-secondary" onclick="window.streamWaveApp.openDetails('${item.id}')">
                            ℹ Details
                        </button>
                    </div>
                </div>
            </article>
        `).join('');

        showView('grid');
    }

    /**
     * Switch view state (loading, error, empty, grid)
     */
    function showView(viewName) {
        elements.loadingState.style.display = viewName === 'loading' ? 'block' : 'none';
        elements.errorState.style.display = viewName === 'error' ? 'block' : 'none';
        elements.emptyState.style.display = viewName === 'empty' ? 'block' : 'none';
        elements.mediaGrid.style.display = viewName === 'grid' ? 'grid' : 'none';
    }

    /**
     * Plays media audio file using HTML5 Audio Player
     */
    async function playMedia(id) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        state.currentTrack = item;
        elements.playerTitle.textContent = item.title;
        elements.playerArtist.textContent = `${item.artist_or_director} (${item.genre})`;
        elements.playerThumb.textContent = item.type === 'music' ? '🎵' : '🎬';

        // Set audio source to static file URL (defaults to /media/demo.wav for demo)
        const audioUrl = item.media_url || '/media/demo.wav';
        elements.audioSource.src = audioUrl;
        elements.audioElement.load();

        try {
            await elements.audioElement.play();
        } catch (e) {
            console.warn('Autoplay prevented or failed:', e);
        }

        // Trigger POST /api/play-events
        logPlayEvent(id);
    }

    /**
     * Fetches a single media item by ID
     */
    async function fetchSingleItem(id) {
        try {
            const res = await fetch(`/api/media/${id}`);
            if (res.ok) return await res.json();
        } catch (e) {
            console.error('Error fetching item detail:', e);
        }
        return null;
    }

    /**
     * Sends playback event log to POST /api/play-events
     */
    async function logPlayEvent(mediaId) {
        updateEventBadge('Logging...', true);
        try {
            const payload = {
                media_id: mediaId,
                session_id: state.sessionId,
                client_timestamp: new Date().toISOString()
            };

            const res = await fetch('/api/play-events', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                const data = await res.json();
                updateEventBadge(`Event Logged (${data.event.server_timestamp.slice(11, 19)} UTC)`, false);
            } else {
                updateEventBadge('Event Log Error', false);
            }
        } catch (err) {
            console.error('Play event error:', err);
            updateEventBadge('Event Log Failed', false);
        }
    }

    /**
     * Updates status dot badge near audio player
     */
    function updateEventBadge(text, isActive) {
        elements.eventLogText.textContent = text;
        if (isActive) {
            elements.eventDot.classList.add('active');
        } else {
            elements.eventDot.classList.remove('active');
        }
    }

    /**
     * Opens accessible details dialog
     */
    async function openDetails(id) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        elements.dialogBody.innerHTML = `
            <div class="dialog-header-meta">
                <span class="meta-tag">${escapeHtml(item.type)}</span>
                <span class="meta-separator">•</span>
                <span style="color: var(--text-secondary); font-size: 0.85rem;">${item.year}</span>
            </div>
            <h2 id="dialog-title" class="dialog-title">${escapeHtml(item.title)}</h2>
            <div class="dialog-artist">By ${escapeHtml(item.artist_or_director)}</div>
            <p id="dialog-desc" class="dialog-description">${escapeHtml(item.description)}</p>

            <div class="dialog-info-grid">
                <div class="info-item">
                    <div class="info-label">Genre</div>
                    <div class="info-value">${escapeHtml(item.genre)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Duration</div>
                    <div class="info-value">${escapeHtml(item.duration)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Media ID</div>
                    <div class="info-value">${escapeHtml(item.id)}</div>
                </div>
            </div>

            <div class="dialog-actions" style="display: flex; gap: 0.75rem;">
                <button class="btn btn-primary" onclick="window.streamWaveApp.playMedia('${item.id}'); document.getElementById('details-dialog').close();">
                    ▶ Play Track Demo
                </button>
            </div>
        `;

        elements.detailsDialog.showModal();
    }

    /**
     * Resets filter parameters
     */
    function resetFilters() {
        state.searchQuery = '';
        state.activeType = '';
        state.activeGenre = '';
        elements.searchInput.value = '';
        elements.genreSelect.value = '';
        elements.clearSearchBtn.style.display = 'none';
        elements.typeTabs.forEach((tab, index) => {
            tab.classList.toggle('active', index === 0);
            tab.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
        });
        fetchMedia();
    }

    /**
     * Basic HTML escaping to prevent XSS
     */
    function escapeHtml(str) {
        if (!str) return '';
        return str
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    // Expose global methods for inline button onclick handlers
    window.streamWaveApp = {
        fetchMedia,
        playMedia,
        openDetails,
        resetFilters
    };

    // Initialize on DOM load
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
